<?php
require __DIR__.'/auth.php';require __DIR__.'/../event-common.php';
$eid=filter_input(INPUT_GET,'event_id',FILTER_VALIDATE_INT);
if(!$eid){header('Location: events.php');exit;}
$s=$conn->prepare('SELECT event_id,title FROM events WHERE event_id=?');$s->bind_param('i',$eid);$s->execute();$event=$s->get_result()->fetch_assoc();$s->close();if(!$event){http_response_code(404);exit('Exhibition not found');}
$s=$conn->prepare("SELECT r.request_id,r.status,r.admin_note,r.requested_at,a.title,u.FULL_NAME,ai.image_path FROM exhibition_requests r JOIN artworks a ON a.artwork_id=r.artwork_id JOIN users u ON u.USER_ID=r.user_id LEFT JOIN artwork_images ai ON ai.image_id=(SELECT MIN(image_id) FROM artwork_images WHERE artwork_id=a.artwork_id) WHERE r.event_id=? ORDER BY FIELD(r.status,'pending','approved','rejected'),r.requested_at DESC");$s->bind_param('i',$eid);$s->execute();$requests=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exhibition Requests | MIRA Admin</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')==='dark'?'dark':'light'}catch(e){}</script><link rel="stylesheet" href="admin.css"><link rel="stylesheet" href="../event.css"><script defer src="admin.js"></script></head><body class="admin-page"><div class="admin-layout"><?php $activeAdminPage='events'; require __DIR__.'/sidebar.php'; ?><main class="admin-main"><header class="admin-topbar"><p class="admin-breadcrumb">MIRA / <strong>Exhibition Requests</strong></p><button id="themeToggle" class="admin-theme-toggle" type="button">☾ Dark mode</button></header><div class="event-container"><p class="event-eyebrow">MIRA · ADMIN STUDIO</p><h1>Artwork exhibition requests ✦</h1><p><a href="events.php">← Back to exhibitions</a></p><h2><?=eventEsc($event['title'])?></h2><p class="event-muted">Approve a student's request to automatically include their artwork in this exhibition. Rejecting a request removes its selection only if it was previously approved through this request.</p><section class="event-request-grid">
<?php foreach($requests as $r):?><article class="event-request-card"><?php if(preg_match('~^uploads/artworks/[a-zA-Z0-9_-]+\.(jpg|jpeg|png|webp)$~i',(string)$r['image_path'])):?><img src="../<?=eventEsc($r['image_path'])?>" alt="<?=eventEsc($r['title'])?>"><?php endif;?><h3><?=eventEsc($r['title'])?></h3><p><?=eventEsc($r['FULL_NAME'])?></p><p class="event-request-status"><?=eventEsc(ucfirst($r['status']))?></p><form method="post" action="review-event-request.php"><input type="hidden" name="csrf" value="<?=eventEsc(eventToken())?>"><input type="hidden" name="event_id" value="<?=(int)$eid?>"><input type="hidden" name="request_id" value="<?=(int)$r['request_id']?>"><label>Admin note (optional)<textarea name="admin_note" maxlength="1000" rows="2"><?=eventEsc($r['admin_note']??'')?></textarea></label><button class="event-primary" name="decision" value="approved" type="submit">Approve</button> <button class="event-outline" name="decision" value="rejected" type="submit">Reject</button></form></article><?php endforeach; ?>
<?php if(!$requests):?><p class="event-card">No artwork requests yet.</p><?php endif;?></section></div></main></div></body></html>
